import ast, io, pathlib, tokenize, sys, difflib

APPLY = '--apply' in sys.argv
ROOT = pathlib.Path('.')

def module_facts(src, path):
    tree = ast.parse(src)
    aliases = set()
    direct = False
    star = False
    local_def = False
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                if a.name == 'harbor.accounts':
                    aliases.add(a.asname or 'harbor')
        elif isinstance(node, ast.ImportFrom):
            if node.module == 'harbor' and node.level == 0:
                for a in node.names:
                    if a.name == 'accounts':
                        aliases.add(a.asname or 'accounts')
            elif node.module == 'harbor.accounts' and node.level == 0:
                for a in node.names:
                    if a.name == 'fetch_user':
                        direct = True
                    elif a.name == '*':
                        star = True
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if node.name == 'fetch_user':
                local_def = True
    return aliases, direct, star, local_def

def offsets(src):
    starts = [0]
    for line in src.splitlines(keepends=True):
        starts.append(starts[-1] + len(line))
    return starts

def transform(src, path):
    aliases, direct, star, local_def = module_facts(src, path)
    starts = offsets(src)
    toks = list(tokenize.generate_tokens(io.StringIO(src).readline))
    # significant token stream (drop NL/NEWLINE/INDENT/DEDENT/COMMENT/ENCODING)
    sig = [t for t in toks if t.type not in (tokenize.NL, tokenize.NEWLINE, tokenize.INDENT,
                                              tokenize.DEDENT, tokenize.COMMENT, tokenize.ENCODING)]
    edits = []  # (start_abs, end_abs, new)
    for i, t in enumerate(sig):
        if t.type == tokenize.NAME and t.string == 'fetch_user':
            if local_def:
                continue
            if direct or star:
                start = starts[t.start[0]-1] + t.start[1]
                end = starts[t.end[0]-1] + t.end[1]
                edits.append((start, end, 'load_account'))
            elif i >= 2 and sig[i-1].string == '.' and sig[i-2].type == tokenize.NAME and sig[i-2].string in aliases:
                start = starts[t.start[0]-1] + t.start[1]
                end = starts[t.end[0]-1] + t.end[1]
                edits.append((start, end, 'load_account'))
    # getattr(alias, "fetch_user")
    import re
    if aliases:
        pat = re.compile(r'(getattr\(\s*(?:' + '|'.join(map(re.escape, aliases)) + r')\s*,\s*)"fetch_user"')
        for m in pat.finditer(src):
            s, e = m.span(1)
            edits.append((s, e, m.group(1) + '"load_account"'))
    # test mock.patch module attributes
    if path.startswith('tests/'):
        pat = re.compile(r'(mock\.patch\("harbor\.[\w.]+\.)fetch_user"')
        for m in pat.finditer(src):
            s, e = m.span(1)
            edits.append((s, e, m.group(1) + 'load_account"'))
    # config handler strings
    for m in re.finditer(r'harbor\.accounts:fetch_user(?=["\'])', src):
        edits.append((m.start() + len('harbor.accounts:'), m.end(), 'load_account'))
    # dedupe + apply from end
    edits = sorted(set(edits), reverse=True)
    out = src
    last = len(src) + 1
    for s, e, new in edits:
        if e > last:
            continue
        out = out[:s] + new + out[e:]
        last = s
    return out

changed = []
for base in ('harbor', 'tests'):
    for p in sorted(pathlib.Path(base).rglob('*.py')):
        if p.as_posix().startswith('harbor/proto/'):
            continue
        if p.as_posix() == 'harbor/accounts/__init__.py':
            continue
        src = p.read_text()
        out = transform(src, p.as_posix())
        if out != src:
            changed.append((p, src, out))
print(len(changed), 'files changed')
for p, src, out in changed:
    print('---', p)
if APPLY:
    for p, src, out in changed:
        p.write_text(out)
    print('APPLIED')
