            elif i >= 2 and sig[i-1].string == '.' and sig[i-2].type == tokenize.NAME and sig[i-2].string in aliases:
                start = starts[t.start[0]-1] + t.start[1]
                end = starts[t.end[0]-1] + t.end[1]
                edits.append((start, end, 'load_account'))
    # getattr(alias, "fetch_user")
    import re
