        for m in pat.finditer(src):
            s, e = m.span(1)
            edits.append((s, e, m.group(1) + '"load_account"'))
    # test mock.patch module attributes
    if path.startswith('tests/'):
        pat = re.compile(r'(mock\.patch\("harbor\.[\w.]+\.)fetch_user"')
